   137	    method: string;
   138	    headers: Record<string, string>;
   139	    authorization: RailAuthorization;
   140	  }): Promise<RailSettlement>;
   141	}
   142	
   143	export class BridgeRail implements PaymentRail {
   144	  constructor(
   145	    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
   146	  ) {}
   147	
   148	  get id(): string {
   149	    return this.idAndBridge.id;
   150	  }
   151	
   152	  quote(req: PaymentRequest): Promise<Quote> {
   153	    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
   154	  }
   155	
   156	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   157	    return this.idAndBridge.bridge.authorize({
   158	      url: String(req.url),
   159	      method: req.method,
   160	      headers: req.headers,
   161	      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
   162	    });
   163	  }
   164	
   165	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   166	    return this.idAndBridge.bridge.settle({
   167	      url: String(req.url),
   168	      method: req.method,
   169	      headers: req.headers,
   170	      authorization,
   171	    });
   172	  }
   173	}
