   175	/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
   176	export class RailRegistry {
   177	  private readonly rails = new Map<string, PaymentRail>();
   178	
   179	  register(rail: PaymentRail): this {
   180	    if (this.rails.has(rail.id)) {
   181	      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
   182	    }
   183	    this.rails.set(rail.id, rail);
   184	    return this;
   185	  }
   186	
   187	  deregister(id: string): boolean {
   188	    return this.rails.delete(id);
   189	  }
   190	
   191	  get(id: string): PaymentRail {
   192	    const r = this.rails.get(id);
   193	    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
   194	    return r;
   195	  }
   196	
   197	  /** Look up a rail by id without throwing when it is absent. */
   198	  optional(id: string): PaymentRail | undefined {
   199	    return this.rails.get(id);
   200	  }
   201	
   202	  ids(): string[] {
   203	    return [...this.rails.keys()].sort();
   204	  }
   205	}
   206	
   207	/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
   208	function deterministicRand(seed: string): () => number {
   209	  let h = 2166136261;
   210	  for (let i = 0; i < seed.length; i++) {
   211	    h ^= seed.charCodeAt(i);
   212	    h = Math.imul(h, 16777619);
   213	  }
   214	  return () => {
   215	    h += 0x6d2b79f5;
   216	    let t = h;
   217	    t = Math.imul(t ^ (t >>> 15), t | 1);
   218	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
   219	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   220	  };
   221	}"}

