{"path": "packages/audit/src/ledger.ts", "start_line": 1, "end_line": 154, "total_lines": 154, "content": "     1	import type {
     2	  Clock,
     3	  FetchOutcome,
     4	  FailureClass,
     5	  LedgerEntry,
     6	} from '@mwb/core';
     7	
     8	/**
     9	 * The ledger is the broker's source of truth: every fetch the broker
    10	 * attempted — fulfilled, denied, failed — appears exactly once.
    11	 *
    12	 * `seq` is monotonically increasing and gap-free; that invariant is what the
    13	 * reconciliation step verifies. If the broker crashes or an origin
    14	 * settlement is missing, reconciliation surfaces it instead of hiding it.
    15	 */
    16	export class AuditLedger {
    17	  readonly entries: LedgerEntry[] = [];
    18	  private seq = 0;
    19	  private readonly clock: Clock;
    20	
    21	  constructor(options?: { clock?: Clock }) {
    22	    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
    23	  }
    24	
    25	  /** Append one row for one fetch attempt. Idempotent per fetchId. */
    26	  record(outcome: FetchOutcome, options?: { tenantId?: string }): LedgerEntry {
    27	    const existing = this.entries.find((e) => e.fetchId === outcome.fetchId);
    28	    if (existing) return existing;
    29	
    30	    this.seq += 1;
    31	    const now = this.clock.now();
    32	    const row: LedgerEntry = {
    33	      seq: this.seq,
    34	      fetchId: outcome.fetchId,
    35	      tenantId: options?.tenantId ?? outcome.tenantId ?? 'default',
    36	      url: outcome.origin?.url ?? 'unknown',
    37	      status: outcome.status === 'fulfilled' ? 'fulfilled' : 'denied',
    38	      failureClass: outcome.failureClass,
    39	      httpStatus: outcome.origin?.httpStatus,
    40	      priceMicros: outcome.price?.unitsMicros,
    41	      currency: outcome.price?.currency,
    42	      rail: outcome.rail,
    43	      licenseId: outcome.license?.id,
    44	      keyId: outcome.identity?.keyId,
    45	      settlementRef: outcome.settlementRef,
    46	      startedAt: outcome.timestamps.startedAt,
    47	      completedAt: outcome.timestamps.completedAt,
    48	      recordedAt: now,
    49	    };
    50	    this.entries.push(row);
    51	    return row;
    52	  }
    53	
    54	  /** Gap-free, monotonically increasing seq. */
    55	  lastSeq(): number {
    56	    return this.seq;
    57	  }
    58	
    59	  byTenant(tenantId: string): LedgerEntry[] {
    60	    return this.entries.filter((e) => e.tenantId === tenantId);
    61	  }
    62	
    63	  byUrl(url: string): LedgerEntry[] {
    64	    return this.entries.filter((e) => e.url === url);
    65	  }
    66	
    67	  toRows(): LedgerEntry[] {
    68	    return this.entries.map((e) => structuredClone(e));
    69	  }
    70	}
    71	
    72	export interface LedgerSummary {
    73	  total: number;
    74	  fulfilled: number;
    75	  denied: number;
    76	  byFailureClass: Record<string, number>;
    77	  spendMicros: number;
    78	  byRail: Record<string, number>;
    79	  byLicense: Record<string, number>;
    80	}
    81	
    82	export function summarize(rows: LedgerEntry[]): LedgerSummary {
    83	  const s: LedgerSummary = {
    84	    total: rows.length,
    85	    fulfilled: 0,
    86	    denied: 0,
    87	    byFailureClass: {},
    88	    spendMicros: 0,
    89	    byRail: {},
    90	    byLicense: {},
    91	  };
    92	  for (const r of rows) {
    93	    if (r.status === 'fulfilled') s.fulfilled += 1;
    94	    else s.denied += 1;
    95	    if (r.failureClass) s.byFailureClass[r.failureClass] = (s.byFailureClass[r.failureClass] ?? 0) + 1;
    96	    if (r.status === 'fulfilled' && r.priceMicros != null) s.spendMicros += r.priceMicros;
    97	    if (r.rail) s.byRail[r.rail] = (s.byRail[r.rail] ?? 0) + 1;
    98	    if (r.licenseId) s.byLicense[r.licenseId] = (s.byLicense[r.licenseId] ?? 0) + 1;
    99	  }
   100	  return s;
   101	}
   102	
   103	export interface ReconciliationReport {
   104	  ok: boolean;
   105	  problems: string[];
   106	  checks: {
   107	    seqGapFree: boolean;
   108	    deniedHasFailureClass: boolean;
   109	    fulfilledHasSettlement: boolean;
   110	    fulfilledHasPrice: boolean;
   111	  };
   112	}
   113	
   114	/**
   115	 * Reconcile the ledger against invariants:
   116	 *  - seq is gap-free starting at 1
   117	 *  - every denied row has a failureClass (the three-classes invariant)
   118	 *  - every fulfilled row has a settlementRef (we paid, we can prove it)
   119	 *  - every fulfilled row has a price (we can bill what we paid)
   120	 */
   121	export function reconcile(rows: LedgerEntry[]): ReconciliationReport {
   122	  const problems: string[] = [];
   123	
   124	  const seqGapFree =
   125	    rows.length === 0 ||
   126	    rows.every((r, i) => r.seq === i + 1);
   127	
   128	  const deniedHaveFC = rows
   129	    .filter((r) => r.status !== 'fulfilled')
   130	    .every((r) => r.failureClass !== undefined);
   131	
   132	  const fulfilledHasSett = rows
   133	    .filter((r) => r.status === 'fulfilled')
   134	    .every((r) => (r.settlementRef ?? '').length > 0);
   135	
   136	  const fulfilledHasPrice = rows
   137	    .filter((r) => r.status === 'fulfilled')
   138	    .every((r) => r.priceMicros != null && r.priceMicros > 0);
   139	
   140	  if (!seqGapFree) problems.push('seq is not gap-free starting at 1');
   141	  if (!deniedHaveFC) problems.push('a denied row lacks a failureClass');
   142	  if (!fulfilledHasSett)
   143	    problems.push('a fulfilled row lacks a settlementRef (settlement not proven)');
   144	  if (!fulfilledHasPrice) problems.push('a fulfilled row lacks a positive price');
   145	
   146	  return {
   147	    ok:
   148	      seqGapFree && deniedHaveFC && fulfilledHasSett && fulfilledHasPrice,
   149	    problems,
   150	    checks: { seqGapFree, deniedHasFailureClass: deniedHaveFC, fulfilledHasSettlement: fulfilledHasSett, fulfilledHasPrice },
   151	  };
   152	}
   153	
   154	export type { FailureClass };"}

{"path": "packages/license/src/engine.ts", "start_line": 1, "end_line": 267, "total_lines": 267, "content": "     1	import { LicenseError } from '@mwb/core';
     2	import type { License, LicenseObligation, RslClause } from '@mwb/core';
     3	
     4	/**
     5	 * License Engine — the broker's compliance layer.
     6	 *
     7	 * Three jobs, all read-only with respect to the network:
     8	 *   1. `parseLicense`     — turn a raw RSL source (a parsed body or a
     9	 *      `Link` header) into a typed `License`.
    10	 *   2. `deriveObligations` — read those terms and produce the concrete,
    11	 *      fetch-scoped obligations the caller must satisfy (attribution,
    12	 *      no-store, pay-per-inference budget, …).
    13	 *   3. `enforce` / `resolveStoreability` — post-fetch checks: did the
    14	 *      caller's actions violate a term?
    15	 *
    16	 * RSL (Really Simple Licensing) terms ride in an HTTP `Link` header, e.g.
    17	 *
    18	 *     Link: <https://licenses.example/r/73>; rel="type:license-terms"
    19	 *
    20	 * with a JSON body that carries the `terms` array. This module builds
    21	 * against that *pattern*; draft field names may drift, so parsing is
    22	 * defensive. Draft-caveat discipline: parse against the shape above, never
    23	 * a draft's exact wire grammar.
    24	 */
    25	
    26	/** A clause, as it appears in an RSL `terms` array. */
    27	export interface RslTermInput {
    28	  type: string;
    29	  value?: boolean | number | string;
    30	  params?: Record<string, string | number>;
    31	}
    32	
    33	/** A parsed RSL body, matching the accepted JSON shape. */
    34	export interface RslBodyLike {
    35	  draft?: string;
    36	  id?: string;
    37	  title?: string;
    38	  publishedAt?: string;
    39	  terms?: RslTermInput[];
    40	}
    41	
    42	export interface LicenseParseOptions {
    43	  /** A `Link` header (or just its URL) identifying the terms document. */
    44	  link?: string;
    45	  /**
    46	   * The raw source string, preserved verbatim on the parsed License for the
    47	   * audit trail. Defaults to whatever was parsed if it was a string.
    48	   */
    49	  rawSource?: string;
    50	}
    51	
    52	/**
    53	 * Parse an RSL source into a License.
    54	 *
    55	 * Accepts:
    56	 *  - a JSON string with a `terms` array (or an `RslBodyLike` object)
    57	 *  - a `Link` header string such as
    58	 *    `<https://licenses.example/r/73>; rel="type:license-terms"`
    59	 *  - `options.link` to attach a terms id when the body carries no `id`.
    60	 */
    61	export function parseLicense(
    62	  source: string | RslBodyLike,
    63	  options: LicenseParseOptions = {}
    64	): License {
    65	  let body: RslBodyLike = { ...(source && typeof source === 'object' ? source : {}) };
    66	  let rawSource: string | undefined = options.rawSource;
    67	
    68	  if (typeof source === 'string') {
    69	    const s = source.trim();
    70	    if (s.startsWith('{')) {
    71	      try {
    72	        body = { ...(JSON.parse(s) as RslBodyLike) };
    73	      } catch (cause) {
    74	        throw new LicenseError(`RSL body is not valid JSON: ${s}`, 'RSL_PARSE', cause);
    75	      }
    76	      rawSource ??= source;
    77	    } else {
    78	      // It is a Link header (or bare URL) identifying the terms doc.
    79	      const link = extractLink(s);
    80	      body.id = body.id ?? link.id;
    81	      body.draft = body.draft ?? link.draft;
    82	      rawSource ??= source;
    83	    }
    84	  }
    85	
    86	  const id = body.id?.trim() || linkId(body.link as string | undefined);
    87	  if (!id) {
    88	    throw new LicenseError('RSL source carried no license identifier', 'RSL_NO_ID');
    89	  }
    90	
    91	  return {
    92	    draft: body.draft?.trim() || 'urn:rsl:draft:unregistered',
    93	    id,
    94	    title: body.title,
    95	    publishedAt: body.publishedAt,
    96	    clauses: normalizeClauses(body.terms),
    97	    rawSource: rawSource ?? body.rawSource ?? `<${id}>`,
    98	  };
    99	}
   100	
   101	/**
   102	 * Derive the fetch-scoped obligations from a license. An empty terms array
   103	 * yields no obligations; the broker still surfaces the `License` so the
   104	 * caller can see what it is (not) bound to.
   105	 */
   106	export function deriveObligations(license: License): LicenseObligation[] {
   107	  const out: LicenseObligation[] = [];
   108	  for (const clause of license.clauses) {
   109	    const { instruction, kind } = clauseToObligation(clause.type, clause.params);
   110	    if (instruction) out.push({ clause: clause.type, kind, instruction });
   111	  }
   112	  return out;
   113	}
   114	
   115	/**
   116	 * Whether the broker may mark the fetched content storeable given the
   117	 * license. A `no-store` marked `forbidden` makes it non-storeable; anything
   118	 * else leaves storeability to the caller.
   119	 */
   120	export function resolveStoreability(license: License): boolean {
   121	  return !license.clauses.some((c) => c.type === 'no-store' && c.value === 'forbidden');
   122	}
   123	
   124	/** Post-fetch actions the caller may have taken. */
   125	export interface EnforcementActions {
   126	  /** Did the caller store/cache the content? */
   127	  store?: boolean;
   128	  /** Attribution notice included when storing, if any (non-empty ⇒ provided). */
   129	  attribution?: string;
   130	  /** Is the usage commercial? */
   131	  commercialUse?: boolean;
   132	  /** Did the caller produce a derivative work from stored content? */
   133	  derived?: boolean;
   134	  /** Number of model inferences run, if any. */
   135	  inferenceCount?: number;
   136	}
   137	
   138	export interface EnforcementResult {
   139	  pass: boolean;
   140	  violations: string[];
   141	  obligations: LicenseObligation[];
   142	}
   143	
   144	/**
   145	 * Check the caller's post-fetch actions against the license. Returns the
   146	 * derived obligations plus any violations — the broker surfaces this so a
   147	 * call that "worked" can still report a compliance problem.
   148	 *
   149	 * Pay-per-inference is advisory (a budget, not a hard gate): the settlement
   150	 * row is the proof of payment, so the engine never blocks on it.
   151	 */
   152	export function enforce(
   153	  license: License,
   154	  actions: EnforcementActions = {}
   155	): EnforcementResult {
   156	  const violations: string[] = [];
   157	
   158	  for (const clause of license.clauses) {
   159	    if (clause.type === 'no-store' && clause.value === 'forbidden' && actions.store) {
   160	      violations.push('no-store: content must not be stored, but store was requested');
   161	    }
   162	    if (clause.type === 'no-commercial-use' && clause.value === 'forbidden' && actions.commercialUse) {
   163	      violations.push('no-commercial-use: usage is commercial, which the license forbids');
   164	    }
   165	    if (
   166	      clause.type === 'no-derivative-works' &&
   167	      clause.value === 'forbidden' &&
   168	      actions.store &&
   169	      actions.derived
   170	    ) {
   171	      violations.push('no-derivative-works: content was stored and transformed');
   172	    }
   173	  }
   174	
   175	  const wantsAttribution = license.clauses.some((c) => c.type === 'attribution' && c.value === 'required');
   176	  if (wantsAttribution && actions.store && !attributionProvided(actions)) {
   177	    violations.push('attribution: content was stored without the required attribution notice');
   178	  }
   179	
   180	  return { pass: violations.length === 0, violations, obligations: deriveObligations(license) };
   181	}
   182	
   183	function attributionProvided(actions: EnforcementActions): boolean {
   184	  return typeof actions.attribution === 'string' && actions.attribution.length > 0;
   185	}
   186	
   187	// --- clause mapping -------------------------------------------------------
   188	
   189	/** Translate a single clause to the obligation it imposes, if any. */
   190	function clauseToObligation(
   191	  type: string,
   192	  params?: Record<string, string | number>
   193	): { instruction?: string; kind: LicenseObligation['kind'] } {
   194	  switch (type) {
   195	    case 'attribution':
   196	      if (params?.by) return { kind: 'notice', instruction: `Include attribution to ${params.by} when using this content.` };
   197	      return { kind: 'notice', instruction: 'Include attribution when using this content.' };
   198	    case 'no-store':
   199	      return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
   200	    case 'no-derivative-works':
   201	      return { kind: 'forbidden', instruction: 'Do not create derivative works from this content.' };
   202	    case 'no-commercial-use':
   203	      return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
   204	    case 'redistribution':
   205	      return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
   206	    default:
   207	      return { kind: 'notice', instruction: `License term ${type} applies; review its conditions.` };
   208	  }
   209	}
   210	
   211	// --- helpers --------------------------------------------------------------
   212	
   213	/** RSL treats a bare clause as required; the engine is predictable about it. */
   214	function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
   215	  if (!terms) return [];
   216	  const out: RslClause[] = [];
   217	  for (const t of terms) {
   218	    if (!t || typeof t.type !== 'string' || !t.type) {
   219	      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
   220	    }
   221	    out.push({
   222	      type: t.type,
   223	      value: t.value ?? 'required',
   224	      params: t.params ?? {},
   225	    });
   226	  }
   227	  return out;
   228	}
   229	
   230	/** Parse a `Link` header (or bare URL) into { id, draft }. */
   231	function extractLink(link: string): { id: string; draft?: string } {
   232	  const url = linkUrl(link);
   233	  if (!url) return { id: '' };
   234	  return { id: slugFromUrl(url), draft: draftFromUrl(url) };
   235	}
   236	
   237	/** A `Link: <url>; rel="..."` or a bare `<url>` / url → the URL string. */
   238	function linkUrl(link: string): string {
   239	  const brace = link.match(/<([^>]*)>/);
   240	  if (brace) return brace[1]!;
   241	  const token = (link.trim().split(/\s|;/)[0] ?? '').trim();
   242	  return token.startsWith('http') ? token : '';
   243	}
   244	
   245	/** https://h.example.com/r/73 → https://h.example.com/r/73. */
   246	function slugFromUrl(url: string): string {
   247	  try {
   248	    return new URL(url).pathname;
   249	  } catch {
   250	    return url;
   251	  }
   252	}
   253	
   254	/** A draft label is best-effort; used only if the body carried no draft. */
   255	function draftFromUrl(url: string): string | undefined {
   256	  try {
   257	    return new URL(url).hostname || undefined;
   258	  } catch {
   259	    return undefined;
   260	  }
   261	}
   262	
   263	/** Alias used by the top-level parse path for a link given via options. */
   264	function linkId(link?: string): string {
   265	  if (!link) return '';
   266	  return extractLink(link.trim()).id;
   267	}"}

